missing = set()
counts = {}
for li, lang in enumerate(LANGS):
    path = f"build/loc/{lang}.xcloc/Localized Contents/{lang}.xliff"
    tree = ET.parse(path)
    root = tree.getroot()
    n = 0
    for unit in root.iter(f"{{{NS}}}trans-unit"):
        src_el = unit.find(f"{{{NS}}}source")
        if src_el is None or src_el.text is None:
            continue
        src = src_el.text
        tgt_el = unit.find(f"{{{NS}}}target")
        if src in T:
            val = T[src][li]
        else:
            missing.add(src)
            val = src
        if tgt_el is None:
            tgt_el = ET.SubElement(unit, f"{{{NS}}}target")
            # place target right after source
            unit.remove(tgt_el)
            unit.insert(list(unit).index(src_el)+1, tgt_el)
        tgt_el.text = val
        n += 1
    tree.write(path, xml_declaration=True, encoding="UTF-8")
    counts[lang] = n

print("units written per lang:", counts)
print("MISSING (no translation, fell back to English):")
for m in sorted(missing):
    print("   ", repr(m))
